{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Deucravacitinib absolute oral bioavailability was 99% in healthy subjects after oral dosing, strongly supporting high bioavailability."
    },
    {
      "card_ids": ["C39"],
      "claim": "GSK1322322 absolute oral bioavailability was 77% after a meal in healthy volunteers, supporting high bioavailability."
    },
    {
      "card_ids": ["C42"],
      "claim": "Isradipine systemic availability was 17% in healthy volunteers after oral administration, supporting low bioavailability."
    }
  ],
  "confidence": "moderate",
  "contradictory_card_ids": ["C42"],
  "decision_summary": "Most transferred evidence with high assay-transfer scores shows absolute oral bioavailability above 20%, including 99%, 77%, 75%, 54.6%, and 32%. One consistently low-bioavailability molecule and some predicted low nilotinib values create moderate uncertainty, but the overall weight supports high bioavailability.",
  "evidence_gaps": [
    "Molecule 1 groups a brigatinib record (C14) with GSK1322322 records; C14 was discounted as a provenance conflict.",
    "Nilotinib has conflicting predicted values (C13 16% vs C30 31%); the strongest absolute fasted record supports high, but low predictions add uncertainty.",
    "Phenserine record C24 is qualitative and not threshold-specific, so it was not used."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C05", "C39"],
  "revision_action": "initial",
  "supportive_card_ids": ["C05", "C39"]
}

